"""Role CRUD + FK enforcement — table "User".roles.

Covers: create role, update role, delete role, delete a role that is
still assigned to a user (FK violation -> service returns 500).
"""

from helpers import db


def test_create_role(api, db_conn):
    """roles.id is GENERATED BY DEFAULT AS IDENTITY (migration 0002).

    The API returns only {is_success} — the id is discarded by the handler
    (RoleResponse has no data field). White-box: read the id back from DB.
    """
    status, body = api.create_role("TestRole_API")

    assert status == 201, f"expected 201, got {status}: {body}"
    assert body["data"]["is_success"] is True

    with db_conn.cursor() as cur:
        cur.execute(
            'SELECT id FROM "User".roles WHERE name = %s', ("TestRole_API",)
        )
        row = cur.fetchone()
    assert row is not None, "role not found in DB after create"
    assert row[0] > 3, "id should be auto-generated past seeded 1-3"

    db.delete_role(db_conn, row[0])


def test_update_role(api, db_conn, role_factory):
    role_id = role_factory()

    status, body = api.update_role(role_id, "RenamedRole")

    assert status == 200, body
    assert body["data"]["is_success"] is True
    assert db.get_role_by_id(db_conn, role_id) == (role_id, "RenamedRole")


def test_delete_role(api, db_conn, role_factory):
    role_id = role_factory()

    status, body = api.delete_role(role_id)

    assert status == 200, body
    assert body["data"]["is_success"] is True
    assert db.get_role_by_id(db_conn, role_id) is None


def test_delete_assigned_role_fails(api, db_conn, role_factory, user_factory):
    """users.role_id REFERENCES roles.id — deleting an in-use role must fail.

    Current service maps the FK violation to HTTP 500.
    """
    role_id = role_factory()
    uid, _ = user_factory(role_id=role_id)
    assert db.get_user_by_uid(db_conn, uid)["role_id"] == role_id

    status, body = api.delete_role(role_id)

    assert status == 500, f"expected 500, got {status}: {body}"
    assert body["data"]["is_success"] is False
    # role must still exist — the delete must have been rejected
    assert db.get_role_by_id(db_conn, role_id) is not None
